const errorData = $json.error;
const executionData = $json.execution;
let orderId = 'N/A';
let workflowName = (executionData && executionData.workflow && executionData.workflow.name) ? executionData.workflow.name : 'N/A';

// Attempt to find orderId in the error context
// This part might need adjustment based on how data flows in your main workflow
// and what's available in the inputData of the failed node.
if (executionData && executionData.lastNodeExecuted && executionData.lastNodeExecuted.inputData && executionData.lastNodeExecuted.inputData.json) {
  const inputJson = executionData.lastNodeExecuted.inputData.json;
  // Check common places where an order ID might be found
  orderId = inputJson.orderId || 
            (inputJson.orderData ? inputJson.orderData.id : null) || 
            inputJson.id || // If the webhook data itself failed early
            (inputJson.json ? (inputJson.json.orderId || (inputJson.json.orderData ? inputJson.json.orderData.id : null)) : null) ||
            'N/A';
}

const subject = `n8n Workflow Error: ${workflowName}`;
const body = `
An error occurred in the n8n workflow: ${workflowName}

Workflow ID: ${executionData.workflow.id}
Execution ID: ${executionData.id}
Failed Node: ${errorData.node.name} (Type: ${errorData.node.type})
Error Message: ${errorData.message}

Order ID (if found): ${orderId}

Error Stack (if available):
${errorData.stack || 'Not available'}

Timestamp: ${new Date().toISOString()}
`;

$json.emailSubject = subject;
$json.emailBody = body;
$json.errorDetails = errorData; // Pass along for further inspection if needed

return $json;
